#' Levene Test
#'
#' 
#' @param data .
#' @param x .
#' @param center .
#' @param a .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$conclusion} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
LeveneTest <- function(
    data,
    x,
    center,
    a = "0.05") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("LeveneTest requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(x), x, NULL))


    options <- LeveneTestOptions$new(
        x = x,
        center = center,
        a = a)

    analysis <- LeveneTestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

